def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    broccoli_patches = image_patch.find("broccoli")
    if not broccoli_patches: return image_patch

    broccoli_patches.sort(key=lambda p: p.horizontal_center)

    right_half = broccoli_patches[max(1, len(broccoli_patches) // 2):]

    if not right_half: return broccoli_patches[0]

    nearest_to_spoon_or_fork = min(right_half, key=lambda p: distance(p, image_patch.crop(*image_patch.get_spoon_or_fork_coords())))

    return nearest_to_spoon_or_fork

def get_spoon_or_fork_coords(self):
    spoon_patches = self.find("spoon")
    fork_patches = self.find("fork")

    if spoon_patches and fork_patches:
        return min(spoon_patches + fork_patches, key=lambda p: p.compute_depth()).get_coords()
    elif spoon_patches:
        return spoon_patches[0].get_coords()
    elif fork_patches:
        return fork_patches[0].get_coords()
    else:
        return None

def get_coords(self):
    return (self.left, self.lower, self.right, self.upper)

def distance(patch_a: ImagePatch, patch_b: ImagePatch) -> float:
    x1, y1, _, _ = patch_a.get_coords()
    x2, y2, _, _ = patch_b.get_coords()
    return math.sqrt((x2 - x1)**2 + (y2 - y1)**2)

