def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    dishes = image_patch.find("dish")
    flowers = image_patch.find("orange flower")

    if not dishes or not flowers:
        return image_patch

    dish_leftish = [d for d in dishes if d.horizontal_center < image_patch.width / 2]
    dish_rightish = [d for d in dishes if d.horizontal_center >= image_patch.width / 2]

    dish_with_flowers = []
    for dish in dish_leftish + dish_rightish:
        for flower in flowers:
            if distance(dish, flower) < 0.1 * min(image_patch.width, image_patch.height):
                dish_with_flowers.append(dish)
                break

    return dish_with_flowers[0] if dish_with_flowers else image_patch

